import "dart:convert"; import "package:dio/dio.dart"; import "../models/user.dart"; import "http_client.dart"; class AuthService { final HttpClient _httpClient = HttpClient(); Future<Map<String, dynamic>> register({required String name, required String email, required String password, required String role, String? mobile, String? reraId}) async { try { final response = await _httpClient.dio.post("/auth/register", data: {"name": name, "email": email, "password": password, "role": role, "mobile": mobile, "reraId": reraId}); return response.data; } on DioException catch (e) { throw _handleError(e); } } Future<Map<String, dynamic>> login({required String email, required String password}) async { try { final response = await _httpClient.dio.post("/auth/login", data: {"email": email, "password": password}); final data = response.data; if (data["token"] != null) { await _httpClient.setToken(data["token"]); } return data; } on DioException catch (e) { throw _handleError(e); } } Future<User> getMe() async { try { final response = await _httpClient.dio.get("/auth/me"); return User.fromJson(response.data["data"]); } on DioException catch (e) { throw _handleError(e); } } Future<Map<String, dynamic>> updateProfile({String? name, String? email, String? mobile}) async { try { final response = await _httpClient.dio.put("/auth/update", data: {"name": name, "email": email, "mobile": mobile}); return response.data; } on DioException catch (e) { throw _handleError(e); } } Future<void> logout() async { await _httpClient.removeToken(); } String _handleError(DioException e) { if (e.response?.data != null && e.response?.data["message"] != null) { return e.response?.data["message"]; } return "An error occurred"; } }
